2647	    for (const std::string &Path : PrefixDirs) {
2648	      if (separator)
2649	        llvm::outs() << llvm::sys::EnvPathSeparator;
2650	      llvm::outs() << Path;
2651	      separator = true;
2652	    }
2653	    for (const std::string &Path : TC.getProgramPaths()) {
2654	      if (separator)
2655	        llvm::outs() << llvm::sys::EnvPathSeparator;
2656	      llvm::outs() << Path;
2657	      separator = true;
